/*字體*/
@import url("https://fontsapi.zeoseven.com/906/main/result.css");

body {
    font-family: "Swei Spring CJK SC";
    font-weight: normal;
}


:root {
    --mesTextPadding: 8%; /*聊天氣泡文字左右內距*/
    --opacity: 0.8; /*圖標透明度*/
    --chat-background-color: var(--SmartThemeChatTintColor);
    --mainFontSize: calc(var(--fontScale)* 16px); /* 主字体大小 */
    --topbarIconSize: calc(var(--mainFontSize)* 1.15); /* 顶栏图标大小 */
    --bottomFormIconSize: calc(var(--mainFontSize)* 1.25);  /*底欄圖標大小*/
    --genericRadius: 0px; /* 通用圆角 */
    --warning: #ce3636;
    --crimson70a: #acacac63;
    --crimson-hover: color-mix(in srgb, var(--SmartThemeUnderlineColor), transparent 90%) !important;
    --standardIconSize: calc(var(--mainFontSize)* 1);
    --bottomFormBlockPadding: calc(var(--mainFontSize) / 1.5);
    --scrollBarWidth: 2px;
    --pagePadding: calc(var(--scrollBarWidth) + 3px);
    --genericLineHeight: calc(var(--mainFontSize)* 1.5); /* 通用行高 */

    /* ==== 所有颜色定义 ==== */
    --topbar-color: color-mix(in srgb, var(--ui-color-main) 80%, transparent); /*頂欄與底欄透明度與顏色*/
    --panel-color: color-mix(in srgb, var(--ui-color-main) 100%, transparent); /*左欄右欄透明度與顏色*/
    --ui-color-main: var(--SmartThemeBlurTintColor);
    --navBackgroundColor: var(--SmartThemeBlurTintColor);
    --utilityColor: #1B1C1E70; /* 说明文字 */
    --buttonFill: color-mix(in srgb, var(--SmartThemeBlurTintColor), white 5%); /* 按钮背景颜色 */
    --menuBackgroundColor: var(--navBackgroundColor); /* 菜单背景颜色 */
    --accentColor: var(--SmartThemeUnderlineColor); /* 装饰色1 思维链，文字装饰，段落装饰等 */
    --accentColorOverlay: color-mix(in srgb, var(--SmartThemeBorderColor), transparent 95%); /* 装饰色2 */
    --scrollBarColor: var(--SmartThemeUnderlineColor); /* 滚动条颜色 */
    --boxShadowSubtle: 1px 1px 0px var(--SmartThemeBorderColor); /* 阴影颜色 */
    --boxShadowSubtleAlt: 1px 1px 0px var(--SmartThemeUnderlineColor); /* 阴影颜色 */
  } 

/*🎀聊天氣泡頂部元素*/
/* 🍺頭像 */
/* 頭像 */
.mes .avatar img {
    height: 120px !important;
    width: 90px !important;
    border-radius: 0% !important; 
    box-shadow: none !important;
}

.mesAvatarWrapper {
    object-fit: cover !important;
    z-index: 5;
    position: absolute;
    top: -110px !important; /* 🐰 頭像上下，負值往上 */
    left: calc(50% - 25px); /* 🐰 頭像左右，修改後面的數字微調 */
    transform: rotate(10deg); /* 🐰 頭像旋轉角度，正值順時針，負值逆時針，0deg為不旋轉 */
}

/* ======================================= */
/* 🐰动图模块🐰  */
/* ======================================= */
.mes[is_user="false"] .avatar {
    position: relative !important; 
}

/* 动图覆盖层：只贴在char的头像上，绝对放过你的头像 */
.mes[is_user="false"] .avatar::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    height: 120px !important;
    width: 90px !important;

    /* 🐰请在这里更换爱的gif图🐰 */
    background-image: url('https://files.catbox.moe/c852k3.gif');

    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    pointer-events: none; 
    border-radius: 0% !important; 
    z-index: 10; 
}

/* 基础共有属性（保持默认粗细不变） */
.mes_edit_buttons, .mes_buttons, .mes_ghost, .mes .name_text, .mesIDDisplay, .mes_timer,
.tokenCounterDisplay,.icon-svg,.timestamp {
  color: #71717c;
  position: absolute !important;
  z-index: 5  !important;
}

/* 🐰 专门精确打击：只让 Token 和 計時 变纤细 */
.tokenCounterDisplay, .mes_timer {
  font-weight: normal !important; 
}
/* 🍺角色名字 */
.mes .name_text {
  top: -35px;
  left: calc(50% - 105px);
  color: #2a2a36 !important; /* 🐰 名字颜色，可在此直接替换其他色值 */
  font-size: 22px;
}

/* 🍺訊息編號 */
.mesIDDisplay {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    white-space: nowrap !important;
    top: -60px;
    left: calc(50% - -85px);
    font-size: 15px !important;
}
/* 🐰 楼层文字 */
.mesIDDisplay::before { content: "定"; margin-right: 4px; }
.mesIDDisplay::after { content: "版"; margin-left: 12px; }

/* 🍺日期時間 */
.timestamp {
    top: -160px;
    left: calc(50% + 90px);
    font-size: 8px;
}

/* 🍺Token */
.tokenCounterDisplay { 
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    white-space: nowrap !important;
    top: -40px;
    left: calc(50% + 95px);
    font-size: 12px !important;
}
/* 🐰 词符文字 */
.tokenCounterDisplay::before { content: "丝带"; margin-right: 4px; }
.tokenCounterDisplay::after { content: " "; margin-left: 6px; }

/* 🍺計時 */
.mes_timer {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    white-space: nowrap !important;
    top: -25px ;
    left: calc(50% + 98px);
    font-size: 12px !important;
}
/* 🐰 计时文字 */
.mes_timer::before { content: "耗时"; margin-right: 4px; }


/* 🍺模型圖標 */
.icon-svg {
    top: -176px;
    left: calc(50% - -250px);
    opacity: 0.6;
}

/* 🍺隱藏訊息小幽靈圖標 */
.mes_ghost {
    top: 46px; 
    left: calc(50% - 320px);
}

/* 🍺小鉛筆 */
.mes_buttons {
    top: 20px !important;
    right: 20px;
}

/* 🍺正文edit按键 */
.mes_edit_buttons {
    filter: drop-shadow(0px 0px 2px var(--buttonFill));
    top: 12px !important;
    right: 14px;
}

  .mes_buttons i, 
  .mes_button i,
  .mes_edit_buttons i,
  .mes_reasoning_actions .edit_button i,
  .mes_buttons .fa-solid,
  .mes_edit_buttons .fa-solid {
    color: var(--SmartThemeUnderlineColor) !important;
    opacity: var(--opacity) !important; 
}

.mes .avatar img, .timestamp, .icon-svg, .mes .name_text, .mes_edit_buttons {
  transform: rotate(-2deg);
}

/* 🐰 修改了三元素的角度 */
.mesIDDisplay, .mes_timer, .tokenCounterDisplay {
  transform: rotate(-10deg) !important;
}

.mes_buttons {
  transform: rotate(-3deg);
}
/* 氣泡頂部裝飾 */
.mes::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 230px; /* 更改裝飾圖片大小。要更動聊天氣泡間隔搜body.bubblechat，更改margin-top的值 */
  background-repeat: no-repeat; 
  background-size: contain; 
  align-items: center !important; 
  background-position: center; 
  top: -180px;
  z-index: 2;
  left: calc(50% - 2px) !important;
  transform: translateX(-50%) rotate(-2deg);
}

/* Char氣泡頂部裝飾 */
.mes[is_user="false"]::before {
  background-image: url('https://i.postimg.cc/C1nrL2Vv/tongbanpinjie-C2.png'); 
}

/* User氣泡頂部裝飾 */
.mes[is_user="true"]::before {
  background-image: url('https://i.postimg.cc/C1nrL2Vv/tongbanpinjie-C2.png'); 
}

/* 疊加紙張紋理 */
.mes::after {
    content: '';
    position: absolute;
    background-image: url('https://www.transparenttextures.com/patterns/black-paper.png');
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    filter: opacity(10%) grayscale(50%) brightness(3);
    pointer-events: none;
    border-radius: inherit; 
    z-index: -1;
}

/* 聊天氣泡底端文字 */
.mes_block::after {
    content: "⚜︎-𝓢𝓱𝓪𝓹𝓲𝓷𝓰-⚜︎";
    display: block;
    text-align: center;
    font-size: 0.9rem;
    color: var(--SmartThemeUnderlineColor);
    margin-top: 20px;      
    margin-bottom: 20px;      
    opacity: 0.6;
}

/* 🎀切換消息 */
.swipeRightBlock,
.swipe_left {  
  left: 22px !important;
  color: var(--SmartThemeUnderlineColor);
}

.swipe_left {
  bottom: 12px;
}

.swipe_left::before {
  content: '⚜︎';
  display: inline-block;
  transform: scaleX(-1);
  opacity: var(--opacity);
}

.swipe_right::before {
  content: '⚜︎';
  opacity: var(--opacity);
}

  /* 🎀底欄&頂欄top bar共通樣式 */
  #top-bar, #send_form, body.no-blur #top-bar, body.no-blur #send_form {
    background-color: var(--topbar-color) !important;
    border: 0px solid var(--SmartThemeBorderColor);
  }

  #top-bar {
    border-bottom: 1px solid var(--SmartThemeBorderColor) !important;
  }

  #send_form, body.no-blur #send_form {
    border-radius: var(--genericRadius);
    border-top: 1px solid var(--SmartThemeBorderColor);
  }

  /* 按鈕 Icon Sizes & Colors */
  .fa, .fa-brands, .fa-classic, .fa-regular, .fa-sharp, .fa-solid, .fab, .far, .fas {
    font-size: var(--standardIconSize);
    color: var(--SmartThemeUnderlineColor);
  } 

/* 🎀頂欄圖標 */

/*頂欄圖標內縮*/
#top-settings-holder {
    padding: 5px !important;
}

.fa-solid:not(#load-spinner) {
  opacity: var(--opacity);
}

#persona-management-button .drawer-icon::before,
#leftNavDrawerIcon::before,
#advanced-formatting-button .drawer-icon::before, 
#user-settings-button .drawer-icon::before,
#extensions-settings-button .drawer-icon::before { 
  content: "♠︎";
  color: var(--SmartThemeUnderlineColor);
  font-size: var(--topbarIconSize);
}

#rightNavDrawerIcon::before,
#table_database_settings_drawer .drawer-icon::before,
#API-status-top:not(.redOverlayGlow)::before,
#WI-SP-button .drawer-icon::before,
#logo_block .drawer-icon::before,
#backgrounds-drawer-toggle .drawer-icon::before {
  content: "🎕";
  color: var(--SmartThemeUnderlineColor);
  font-size: var(--topbarIconSize)
}

/* 🎀底欄(by Nakari)  */

#send_form .fa-solid {
  font-size: var(--bottomFormIconSize); /*底欄圖標大小*/
  opacity: var(--opacity) !important;
  color: var(--SmartThemeUnderlineColor); /*底欄顏色*/
}

#send_form textarea {
  border: none !important;
}

/* 菜单 */
#options_button::before {
    content: "🍸";
}

/* 扩展 */
#extensionsMenuButton::before {
    content: "🍴";
}

/* 发送消息 在这里更换你想要的星座 */
#send_but::before {
    content: "♏︎";
    transform: scaleX(-1);
}

/* 底栏输入框文案隐藏 */
#send_textarea::placeholder {
    opacity: 0;
}

/*打字時輸入框透明度*/
#send_textarea:focus {
        background-color: var(--ui-color-main) !important;
        background: var(--ui-color-main) !important;
}

/* 🎀输入框换行(來自Nakari)*/
@media (max-width: 768px) {
    #nonQRFormItems {
        display: grid;
        grid-template-columns: auto 1fr auto;
        grid-template-rows: auto auto;
        place-items: center;
        padding: 0 10px 8px 10px !important; /*底欄圖標內縮*/

    }

    #leftSendForm {
        grid-row: 1 / 2;
        grid-column: 1 / 2;
    }

    #rightSendForm {
        grid-row: 1 / 2;
        grid-column: 3 / 4;
    }

    #send_textarea:focus {
        grid-row: 2 / 3;
        grid-column: 1 / 4;
        justify-self: center;
        width: 97%; /* 输入框宽度 */
        margin: 0px 0px -5px; /* 上、左右、下方间距 */
    }
}

/* 🎀extensionTopBar */
#extensionTopBar, #extensionConnectionProfiles {
  border-radius: 0px !important;
  border: 0 !important;
  background-color: var(--topbar-color) !important;
}

#extensionTopBar .right_menu_button {
  opacity: var(--opacity) !important;
  color: var(--SmartThemeUnderlineColor) !important;
}

#extensionTopBarChatName, #extensionTopBarSearchInput {
  border: none !important;
  box-shadow: none !important;
  background: none !important;
}

/* 🎀正文 */
/* 聊天气泡 */
  body.bubblechat .mes {
    border-radius: var(--genericRadius);
    margin-top: 200px; /* 聊天氣泡間隔 */
    display: flex;
    flex-direction: column;
    z-index: 0;
    padding: 50px var(--mesTextPadding) 0px var(--mesTextPadding);
  }

  .mes_text {
    line-height: var(--genericLineHeight);
    text-align: justify;
    z-index: 5 !important;
    padding: 0px;
  }

.mes_text p {
    margin-bottom: 1.8em; /*段距*/
  }

 /* 對白樣式 */
.mes_text q {
  color: var(--SmartThemeQuoteColor); 
  background: linear-gradient(135deg, rgba(160, 180, 199, 0.08), rgba(160, 180, 199, 0.04));
  border-left: 3px double rgba(160, 180, 199, 0.3);
  margin: 0px 6px 0px 3px;
  padding: 0px 0px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.0);
  position: relative;
}

/* 引用塊 */
.mes_text blockquote {
  background: color-mix(in srgb, var(--SmartThemeUnderlineColor) 10%, transparent);
  border-left: 3px double var(--SmartThemeUnderlineColor);
  padding: 16px 24px;    
  border-radius: var(--genericRadius);
  margin-bottom: 15px;
}

  .last_mes .mesAvatarWrapper {
    padding-bottom: 5px !important;
  }

  .mes_block {
    padding-left: 0px !important;
  }


/* 🎀Loadingpage by旅程美化交流帖*/
#load-spinner {
  --spinner-size: 180px;
  opacity: 1;
  top: calc(50% - var(--spinner-size) / 2);
  left: calc(50% - var(--spinner-size) / 2);
  position: absolute;
  width: var(--spinner-size);
  height: var(--spinner-size);
  background-image: url('https://pub-ab57b744470342a2aea5107d958a034e.r2.dev/sillytavern/L5.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  animation: none !important;
}

#load-spinner::before {
  display: none !important;
}

/* 消除加载界面弹窗色块：背景透明、去阴影(by@Nuyoah) */
body:has(#load-spinner) .popup {
    background-color: transparent !important;
    box-shadow: none !important;
    border: none !important;
}

  /* 🎀聊天框背景 */
  #chat {
    padding: var( --pagePadding) 3px var( --pagePadding) var( --pagePadding);
    overflow-y: scroll;
    border: 0px solid var(--SmartThemeBorderColor);
    border-top: none;
    border-bottom: none;
  }

  #form_sheld {
    margin-top: 0px !important;
  }

  #top-bar {
    height: var(--topBarBlockSize);
  }

  #extensions_settings .inline-drawer-toggle.inline-drawer-header,
  #extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
  #user-settings-block h4,
  .standoutHeader,
  .userSettingsInnerExpandable {
    border: transparent !important;
  }

  .drawer-content, #right-nav-panel, #left-nav-panel {
    border-radius: var(--genericRadius);
    padding: 8px;
    border-top: 0;
    border-right: 1px solid var(--SmartThemeBorderColor);
    border-bottom: 1px solid var(--SmartThemeBorderColor);
    border-left: 1px solid var(--SmartThemeBorderColor);
    padding-top: 8px;
  }


  #right-nav-panel, #left-nav-panel {
    border-top: 1px solid var(--SmartThemeBorderColor);
    background-color: var(--panel-color) !important;
    border-left: none;
  }

  /* 预设icons */
  #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt_manager_prompt_controls span {
    color: var(--SmartThemeBodyColor)  !important;
  }

    /* 按钮圆角统一 */
  #character_sort_order,
  #form_character_search_form .menu_button, 
  #GroupFavDelOkBack .menu_button,
  .regex-script-label,
  .menu_button {
    border-radius: var(--genericRadius) !important;
  }

  .regex-script-label {
    border: none !important;
  }

  /* 对话框icons */
  .mes_button {
    color: var(--SmartThemeBodyColor);
  }

  #table_button_container {
    background-color: var(--buttonFill) !important; 
  }



  /* 标题样式 */

  /* 清除设置页相关模块标题的背景图，并精简上下 padding */
  #extensions_settings .inline-drawer-toggle.inline-drawer-header,
  #extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
  #user-settings-block h4, .standoutHeader{
    background-image: none !important;
    padding: 2px 0 !important;
  }

 /* 原始元素样式 */
  .standoutHeader:not(h4),
  #rm_PinAndTabs,
  #title_api,
  #rm_api_block .flex-container.alignItemsBaseline,
  #AdvancedFormatting .flex-container.alignItemsBaseline:not(h3),
  #WorldInfo .alignitemscenter:not(#world_popup *),
  #user-settings-block div[name="userSettingsRowOne"],
  #rm_extensions_block .alignitemscenter.flex-container.wide100p:not(.justifyCenter),
  #top-settings-holder .drawer:not(:first-child):not(:last-child) .drawer-content .alignItemsBaseline.wide100p {
    position: relative; /* 必须要有 */
    padding-left: 12px;
    margin-top: calc(var(--mainFontSize) * 0.2) !important;
    margin-bottom: calc(var(--mainFontSize) * 0.2) !important;
  }

  /* 小竖线 */
  #rm_PinAndTabs::before,
  #title_api::before,
  #rm_api_block .flex-container.alignItemsBaseline::before,
  #AdvancedFormatting .flex-container.alignItemsBaseline:not(h3)::before,
  #WorldInfo .alignitemscenter:not(#world_popup *)::before,
  #user-settings-block div[name="userSettingsRowOne"]::before,
  #rm_extensions_block .alignitemscenter.flex-container.wide100p:not(.justifyCenter)::before,
  #top-settings-holder .drawer:not(:first-child):not(:last-child) .drawer-content .alignItemsBaseline.wide100p::before {
    content: '';
    position: absolute;
    left: 0;
    top: 6px;
    bottom: 6px;
    width: 3px;
    background-color: var(--SmartThemeUnderlineColor);
    border-radius: 1px;
  }

  /* === 统一标题文字的行高（使阅读更舒适）=== */
  .standoutHeader strong,
  #right-nav-panel h2,
  .drawer-content > h3,
  .drawer-content .flex-container h3:first-of-type:not(#Backgrounds .textAlignCenter),
  .drawer-content .flex-container .flex-container h3:first-of-type,
  .popup h3:not(dialog *) {
    line-height: var(--genericLineHeight);
  }

  .flex-container {
    gap: 8px;
  }

  .redOverlayGlow {
    color: #9c2c2c;
  }

  /* menu颜色 */
  .ui-widget.ui-widget-content,
  #bulk_tag_popup,
  #dialogue_popup,
  .popup,
  #options,
  #extensionsMenu,
  .popup .popper-modal,
  .select2-dropdown,
  #select_chat_popup,
  #floatingPrompt,
  #cfgConfig,
  #logprobsViewer,
  #movingDivs > div {
    border-radius: var(--genericRadius);
    background-color: var(--menuBackgroundColor);
    box-shadow: var(--boxShadowSubtle);
  }

  #options, #extensionsMenu {
    border: 1px solid var(--SmartThemeBorderColor);
  }

  .extensions_toolbar {
    background-color: var(--menuBackgroundColor);
  }

  /* 统一样式 */
  #ccs-preview-modal > div,
  .bg_example, #toast-container > div,
  .bg_example:hover, #toast-container > div:hover {
    border-radius: var(--genericRadius) !important;
    border: 1px solid var(--SmartThemeBorderColor) !important;
    box-shadow: var(--boxShadowSubtle) !important;
  }

  .list-group, .extensions_info .extension_block, #completion_prompt_manager_popup {
    border-radius: var(--genericRadius);
    border-left: 1px solid var(--SmartThemeBorderColor);
    border-right: 1px solid var(--SmartThemeBorderColor);
    border-bottom: 1px solid var(--SmartThemeBorderColor);
  }

  .options-content {
    border: none;
  }

  /* 背景添加页面 */
  .bg_example.no-border.no-shadow.add_bg_but.interactable {
    background-color: var(--SmartThemeUnderlineColor);
  }   

  .BGSampleTitle {
    border-radius: var(--genericRadius);
  }

   /* 角色卡添加tag */
  body .ui-widget-content li:hover {
    background-color: var(--SmartThemeUnderlineColor);
  }

